package com.ias.asset;
import com.ias.trust.Problem;import org.junit.jupiter.api.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.*;import org.springframework.transaction.support.TransactionTemplate;import java.util.*;import java.sql.Connection;import java.util.concurrent.*;import static org.junit.jupiter.api.Assertions.*;
class MembershipRoleServiceTest {
 JdbcTemplate db;Connection ddl;MembershipRoleService service;boolean permitted=true;Set<Long> live=ConcurrentHashMap.newKeySet();MembershipRoleAccess.Actor actor=new MembershipRoleAccess.Actor(7,900,null,null,"test",Long.MAX_VALUE);
 @BeforeEach void prepare()throws Exception{var ds=new DriverManagerDataSource("jdbc:h2:mem:"+UUID.randomUUID()+";MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1","sa","");db=new JdbcTemplate(ds);ddl=ds.getConnection();ddl.createStatement().execute("CREATE TABLE asset_company(id BIGINT PRIMARY KEY,tenant_id BIGINT,status VARCHAR(20));CREATE TABLE asset_membership(id BIGINT PRIMARY KEY,tenant_id BIGINT,company_id BIGINT,user_id BIGINT,state VARCHAR(20),row_version BIGINT,updated_at TIMESTAMP(3))");try(var in=getClass().getResourceAsStream("/db/migration/V3__membership_administrator_roles.sql")){ddl.createStatement().execute(new String(in.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8).replace("CHARACTER SET ascii COLLATE ascii_bin","").replace("ENGINE=InnoDB","").replace(" JSON NOT NULL"," VARCHAR(8192) NOT NULL"));}db.update("INSERT INTO asset_company VALUES(31,7,'ENABLED'),(32,8,'ENABLED')");db.update("INSERT INTO asset_membership VALUES(51,7,31,41,'ACTIVE',1,CURRENT_TIMESTAMP),(52,7,31,42,'ACTIVE',1,CURRENT_TIMESTAMP),(53,7,31,43,'PROVISIONING',1,CURRENT_TIMESTAMP)");live.addAll(List.of(41L,42L,43L));var tx=new TransactionTemplate(new DataSourceTransactionManager(ds));tx.setIsolationLevel(2);tx.setTimeout(5);service=new MembershipRoleService(db,tx,new MembershipRoleAccess(){public void current(Actor a,boolean write){if(!permitted)throw new Problem(403,"ACCESS_DENIED");}public Set<Long> eligible(Actor a,Collection<Long> users){var found=new HashSet<Long>(users);found.retainAll(live);return found;}});}
 @AfterEach void close()throws Exception{ddl.close();}
 String op(){return UUID.randomUUID().toString();}Map<String,Object> change(long m,String op,long v,String role){return service.change(actor,31,m,op,v,role);}long count(String t){return db.queryForObject("SELECT COUNT(*) FROM "+t,Long.class);}long version(long m){return db.queryForObject("SELECT row_version FROM asset_membership WHERE id=?",Long.class,m);}
 @Test void legacyDefaultMemberIsNotImplicitAdmin(){assertEquals("MEMBER",service.view(actor,31,51).get("role"));assertFalse(MembershipRoleService.administrator(db,7,31,41));assertEquals(0,count("asset_membership_role"));assertEquals(1,version(51));}
 @Test void explicitGrantOriginalKeyReplayAndQueryAreSingleImmutableFacts(){String key=op();var first=change(51,key,1,"ADMIN");assertEquals(first,change(51,key,1,"ADMIN"));assertEquals(first,service.operation(actor,31,key));assertTrue(MembershipRoleService.administrator(db,7,31,41));assertEquals(1,count("asset_membership_role_operation"));assertEquals(1,count("asset_membership_role_audit"));assertEquals(2,version(51));assertEquals("IDEMPOTENCY_CONFLICT",assertThrows(Problem.class,()->change(51,key,1,"MEMBER")).code);}
 @Test void currentPermissionPrecedesHistoricalPostAndQuery(){String key=op();change(51,key,1,"ADMIN");permitted=false;assertEquals(403,assertThrows(Problem.class,()->change(51,key,1,"ADMIN")).status);assertEquals(403,assertThrows(Problem.class,()->service.operation(actor,31,key)).status);assertEquals(2,version(51));}
 @Test void currentTenantCompanyMemberAndOriginalActorAreBound(){String key=op();change(51,key,1,"ADMIN");assertEquals(404,assertThrows(Problem.class,()->service.view(new MembershipRoleAccess.Actor(8,900,null,null,"t",Long.MAX_VALUE),31,51)).status);assertEquals(404,assertThrows(Problem.class,()->service.operation(new MembershipRoleAccess.Actor(7,901,null,null,"t",Long.MAX_VALUE),31,key)).status);assertEquals(404,assertThrows(Problem.class,()->service.view(actor,31,999)).status);}
 @Test void lastUsableAdminCannotBeRemovedEvenWhenAnotherIdentityIsDisabled(){change(51,op(),1,"ADMIN");assertEquals("LAST_ENTERPRISE_ADMIN",assertThrows(Problem.class,()->change(51,op(),2,"MEMBER")).code);change(52,op(),1,"ADMIN");live.remove(42L);assertEquals("LAST_ENTERPRISE_ADMIN",assertThrows(Problem.class,()->change(51,op(),2,"MEMBER")).code);assertEquals(2,version(51));}
 @Test void provisioningOrDisabledCustomerCannotReceiveAdmin(){assertEquals("CUSTOMER_ADMIN_INELIGIBLE",assertThrows(Problem.class,()->change(53,op(),1,"ADMIN")).code);live.remove(41L);assertEquals("CUSTOMER_ADMIN_INELIGIBLE",assertThrows(Problem.class,()->change(51,op(),1,"ADMIN")).code);assertEquals(0,count("asset_membership_role"));}
 @Test void auditFailureRollsBackAllFactsThenSameUuidRecovers(){String key=op();db.execute("ALTER TABLE asset_membership_role_audit ADD CONSTRAINT qa_role_audit CHECK(actor_user_id<>900)");assertThrows(Exception.class,()->change(51,key,1,"ADMIN"));assertEquals(1,version(51));assertEquals(0,count("asset_membership_role"));assertEquals(0,count("asset_membership_role_operation"));db.execute("ALTER TABLE asset_membership_role_audit DROP CONSTRAINT qa_role_audit");change(51,key,1,"ADMIN");assertEquals(2,version(51));assertEquals(1,count("asset_membership_role_operation"));}
 @Test void concurrentRevokeCannotRemoveBothAdmins()throws Exception{change(51,op(),1,"ADMIN");change(52,op(),1,"ADMIN");var gate=new CountDownLatch(1);try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var futures=new ArrayList<Future<String>>();for(long m:List.of(51L,52L))futures.add(pool.submit(()->{gate.await();try{change(m,op(),2,"MEMBER");return "OK";}catch(Problem p){return p.code;}}));gate.countDown();var results=List.of(futures.get(0).get(),futures.get(1).get());assertEquals(1,results.stream().filter("OK"::equals).count());assertEquals(1,results.stream().filter("LAST_ENTERPRISE_ADMIN"::equals).count());}assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM asset_membership_role WHERE role_code='ADMIN'",Integer.class));assertEquals(3,count("asset_membership_role_audit"));}
 @Test void companyOrMembershipDisableRemovesFinanceAdminProjection(){change(51,op(),1,"ADMIN");db.update("UPDATE asset_company SET status='DISABLED' WHERE id=31");assertFalse(MembershipRoleService.administrator(db,7,31,41));db.update("UPDATE asset_company SET status='ENABLED' WHERE id=31");db.update("UPDATE asset_membership SET state='PROVISIONING' WHERE id=51");assertFalse(MembershipRoleService.administrator(db,7,31,41));}
}
